import { test, expect } from '@playwright/test';

test.describe('Keyboard Navigation Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should navigate to the first interactive element using Tab', async ({ page }) => {
    await page.keyboard.press('Tab');
    const firstInteractiveElement = await page.getByRole('button', { name: /submit/i });
    await expect(firstInteractiveElement).toBeFocused();
  });

  test('should navigate through all interactive elements using Tab', async ({ page }) => {
    const interactiveElements = await page.locator('button, [href], input, select, textarea').count();

    for (let i = 0; i < interactiveElements; i++) {
      await page.keyboard.press('Tab');
      const focusedElement = await page.evaluate(() => document.activeElement);
      expect(focusedElement).toBeTruthy();
    }

    await page.keyboard.press('Tab'); // Move to the last element
    const lastInteractiveElement = await page.getByRole('button', { name: /cancel/i });
    await expect(lastInteractiveElement).toBeFocused();
  });
});
